            r2 = 2.0 * (static_cast<double>(std::rand()) / RAND_MAX - 0.5);
            r = r1*r1 + r2*r2;
        } while (r >= 1.0 || r == 0.0);

        double fac = std::sqrt(-2.0 * std::log(r) / r);
        double v_x = r1 * fac * sigma;

        do {
            r1 = 2.0 * (static_cast<double>(std::rand()) / RAND_MAX - 0.5);
            r2 = 2.0 * (static_cast<double>(std::rand()) / RAND_MAX - 0.5);
            r = r1*r1 + r2*r2;
        } while (r >= 1.0 || r == 0.0);

        fac = std::sqrt(-2.0 * std::log(r) / r);
        double v_y = r1 * fac * sigma;

        do {
            r1 = 2.0 * (static_cast<double>(std::rand()) / RAND_MAX - 0.5);
            r2 = 2.0 * (static_cast<double>(std::rand()) / RAND_MAX - 0.5);
            r3 = r1*r1 + r2*r2;
        } while (r3 >= 1.0 || r3 == 0.0);

        // Use the Box-Muller method to generate the z-component
        double r_c = std::sqrt(-2.0 * std::log(r3) / r3);
        double v_z = r1 * r_c * sigma;

        velocities[i].x = v_x;
        velocities[i].y = v_y;
        velocities[i].z = v_z;
